    await moved(2, 1, 1);
    assert.deepEqual((await live(1)).map(task => task.id), [1, 2, later.id]);
    assert.deepEqual((await tasks(1))[0], original);
    await summary(1, 3, 1);
    await summary(2, 0, 0);
  } finally {
    await stop();
    await rm(directory, { recursive: true, force: true });
  }
});
