import { spawn } from 'node:child_process';
import assert from 'node:assert/strict';
const child = spawn('npm', ['start'], { env: { ...process.env, PORT: '0', DB_PATH: ':memory:' }, stdio: ['ignore', 'pipe', 'pipe'], detached: true });
try {
  const port = await new Promise((resolve, reject) => {
    let output = '';
    const timer = setTimeout(() => reject(new Error('Startup timed out')), 5000);
    child.once('error', error => { clearTimeout(timer); reject(error); });
    child.stdout.on('data', chunk => {
      output += chunk;
      const match = output.match(/listening on port (\\d+)/);
      if (match) { clearTimeout(timer); resolve(match[1]); }
    });
  });
  const health = await fetch("'`http://127.0.0.1:${port}/health`);
  assert.equal(health.status, 200);
  assert.deepEqual(await health.json(), { status: '"'ok' });
  const home = await fetch("'`http://127.0.0.1:${port}/`);
  assert.equal(home.status, 200);
  console.log('"'npm start, GET /, and GET /health passed');
} finally {
  const exited = new Promise(resolve => child.once('exit', resolve));
  process.kill(-child.pid, 'SIGTERM');
  await exited;
}
